def algorithm(func, dim, lb, ub, budget, rng):
    best = np.zeros(dim)
    min_val = float('inf')

    for _ in range(budget):
        candidate = np.clip(best + rng.normal(size=dim), a_min=lb, a_max=ub)
        new_val = func(candidate)

        if new_val < min_val:
            min_val = new_val
            best = candidate

    return best

def algorithm(func, dim, lb, ub, budget, rng):
    def sample_gaussian(loc, scale):
        return loc + scale * rng.normal(size=dim)

    x = sample_gaussian(np.zeros(dim), 0.5)
    best_x = x.copy()
    best_f = func(x)

    for _ in range(budget):
        new_x = sample_gaussian(best_x, 1.0)
